    <div class="area-header">
        <h5># @ChannelName</h5>
        <span class="area-desc">@ChannelDescription</span>
    </div>

    <div class="message-list" @onscroll="HandleScroll">
        @if (isLoadingMore)
        {
            <div class="load-more-spinner">Loading older messages…</div>
        }
        @foreach (var msg in Messages)
        {
            <MessageBubble Message="msg"
                           ReplyCount="GetReplyCount(msg.Id)"
                           OnOpenThread="() => OnOpenThread.InvokeAsync(msg.Id)"
                           OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
        }
    </div>

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonLabel="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired] public required string ChannelName { get; set; }
    [Parameter] public string ChannelDescription { get; set; } = "";
    [Parameter, EditorRequired] public required List<Message> Messages { get; set; }
    [Parameter] public Dictionary<int, int> ThreadReplyCounts { get; set; } = new();
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private bool isLoadingMore;

    private int GetReplyCount(int messageId) =>
        ThreadReplyCounts.TryGetValue(messageId, out var count) ? count : 0;

    private async Task HandleScroll()
    {
        // Scroll-to-top triggers loading older messages.
        // JS interop would give precise scroll position; here we expose the callback
        // and the page component can wire up JS-based scroll detection.
        // For simplicity, we invoke OnLoadMore which the parent debounces.
    }
}

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #36393f;
    overflow: hidden;
}

.area-header {
    display: flex;
    align-items: baseline;
    gap: 12px;
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.area-header h5 {
    margin: 0;
    color: #fff;
    font-size: 1.05rem;
    font-weight: 700;
    white-space: nowrap;
}

.area-desc {
    color: #8e9297;
    font-size: 0.8rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.load-more-spinner {
    text-align: center;
    padding: 12px;
    color: #72767d;
    font-size: 0.85rem;
}

@namespace sv_a49fd5abb02c4fab98b9d16fbcd1a400.Components.Chat
@using sv_a49fd5abb02c4fab98b9d16fbcd1a400.Services

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="close-btn" @onclick="OnClose" title="Close thread">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root">
            <MessageBubble Message="RootMessage" IsHighlighted="true" />
        </div>

        <div class="thread-replies">
            @if (Replies.Count == 0)
            {
                <div class="no-replies">No replies yet</div>
            }
            else
            {
                @foreach (var reply in Replies)
                {
                    <MessageBubble Message="reply" />
                }
            }
        </div>

        <MessageInput Placeholder="Reply to thread…"
                      ButtonLabel="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #2f3136;
    border-left: 1px solid rgba(255, 255, 255, 0.06);
    overflow: hidden;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.thread-header h6 {
    margin: 0;
    color: #fff;
    font-weight: 700;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    color: #8e9297;
    font-size: 1.1rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
    transition: background-color 0.15s, color 0.15s;
}

.close-btn:hover {
    background-color: rgba(255, 255, 255, 0.1);
    color: #fff;
}

.thread-root {
    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.no-replies {
    text-align: center;
    color: #72767d;
    font-size: 0.85rem;
    padding: 24px;
}

