    border-bottom: 1px solid rgba(255, 255, 255, 0.06);
    flex-shrink: 0;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.no-replies {
    text-align: center;
    color: #72767d;
    font-size: 0.85rem;
    padding: 24px;
}

