arguments.file_text:
@page "/chat"
@namespace sv_a49fd5abb02c4fab98b9d16fbcd1a400.Components.Pages
@using sv_a49fd5abb02c4fab98b9d16fbcd1a400.Components.Chat
@using sv_a49fd5abb02c4fab98b9d16fbcd1a400.Services
@rendermode InteractiveServer
@inject IChatService ChatService
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="channels"
                        ActiveChannelId="activeChannelId"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(isThreadOpen ? "" : "expanded")">
        @if (activeChannel is not null)
        {
            <MessageArea ChannelName="@activeChannel.Name"
                         ChannelDescription="@activeChannel.Description"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage"
                         OnLoadMore="LoadOlderMessages" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private List<Channel> channels = new();
    private List<Message> messages = new();
    private Dictionary<int, int> threadReplyCounts = new();

    private Channel? activeChannel;
    private int activeChannelId;

    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadReplies = new();

    private const int PageSize = 30;
    private bool hasMoreMessages = true;
    private bool isLoadingMore;

    private IJSObjectReference? scrollModule;
    private DotNetObjectReference<Chat>? dotNetRef;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            dotNetRef = DotNetObjectReference.Create(this);
            scrollModule = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-a49fd5abb02c4fab98b9d16fbcd1a400/js/chat-scroll.js");
            await scrollModule.InvokeVoidAsync("initScrollDetection", dotNetRef);
        }
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        await LoadOlderMessages();
    }

    private async Task SelectChannel(int channelId)
    {
        activeChannelId = channelId;
        activeChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messages.Clear();
        threadReplyCounts.Clear();
        hasMoreMessages = true;
        isThreadOpen = false;

        await LoadMessages();
        _ = ChatService.MarkChannelReadAsync(channelId);

        // Update unread count locally
        var idx = channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            channels[idx] = channels[idx] with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages()
    {
        var batch = await ChatService.GetMessagesAsync(activeChannelId, messages.Count, PageSize);
        if (batch.Count < PageSize) hasMoreMessages = false;

        // Insert older messages at the beginning
        messages.InsertRange(0, batch);
        await BuildThreadCounts();
    }

    private async Task LoadOlderMessages()
    {
        if (!hasMoreMessages || isLoadingMore) return;
        isLoadingMore = true;
        StateHasChanged();

        await LoadMessages();

        isLoadingMore = false;
        StateHasChanged();
    }

    private async Task BuildThreadCounts()
    {
        // Build reply counts from messages that have ReplyToId set
        threadReplyCounts.Clear();
        foreach (var msg in messages.Where(m => m.ReplyToId.HasValue))
        {
            var rootId = msg.ReplyToId!.Value;
            threadReplyCounts.TryGetValue(rootId, out var count);
            threadReplyCounts[rootId] = count + 1;
        }
    }

    private async Task OpenThread(int messageId)
    {
        // Find the root message (either this message or the root it replies to)
        var rootId = messageId;
        var clicked = messages.FirstOrDefault(m => m.Id == messageId);
        if (clicked?.ReplyToId.HasValue == true)
        {
            rootId = clicked.ReplyToId.Value;
        }

        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootId);
        threadReplies = await ChatService.GetThreadAsync(rootId);
        isThreadOpen = true;
    }

    private async Task CloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadReplies.Clear();
    }

    private async Task SendMessage(string content)
    {
        var sent = await ChatService.SendMessageAsync(activeChannelId, content, null);
        messages.Add(sent);
    }

    private async Task SendThreadReply(string content)
    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            activeChannelId, content, threadRootMessage.Id);

        threadReplies.Add(reply);
        messages.Add(reply);

        // Update thread count
        threadReplyCounts.TryGetValue(threadRootMessage.Id, out var count);
        threadReplyCounts[threadRootMessage.Id] = count + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Optimistic update
        var idx = messages.FindIndex(m => m.Id == args.MessageId);
        if (idx >= 0)
        {
            var msg = messages[idx];
            var reactions = msg.Reactions.ToList();
            var existing = reactions.FindIndex(r => r.Emoji == args.Emoji);
            if (existing >= 0)
            {
                var r = reactions[existing];
                if (!r.Users.Contains("You"))
                {
                    reactions[existing] = r with { Users = [.. r.Users, "You"] };
                }
            }
            else
            {
                reactions.Add(new Reaction(args.Emoji, ["You"]));
            }
            messages[idx] = msg with { Reactions = reactions };
        }
    }

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        if (scrollModule is not null)
        {
            try { await scrollModule.DisposeAsync(); } catch { }
        }
        dotNetRef?.Dispose();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    background-color: #36393f;
    color: #dcddde;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.chat-sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.chat-main {
    flex: 1;
    min-width: 0;
    transition: flex 0.2s ease;
}

.chat-main.expanded {
    flex: 1;
}

.chat-thread {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.empty-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #72767d;
    font-size: 1.1rem;
}

