    {
        if (threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(
            activeChannelId, content, threadRootMessage.Id);

        threadReplies.Add(reply);
        messages.Add(reply);

        // Update thread count
        threadReplyCounts.TryGetValue(threadRootMessage.Id, out var count);
        threadReplyCounts[threadRootMessage.Id] = count + 1;
    }

