// Detects when the message list is scrolled to the top to trigger loading older messages.
export function initScrollDetection(dotNetRef) {
    const observer = new MutationObserver(() => {
        const messageList = document.querySelector('.message-list');
        if (messageList && !messageList._scrollBound) {
            messageList._scrollBound = true;
            messageList.addEventListener('scroll', () => {
                if (messageList.scrollTop <= 20) {
                    dotNetRef.invokeMethodAsync('OnScrolledToTop');
                }
            });
        }
    });

    observer.observe(document.body, { childList: true, subtree: true });
}

